  const len = text.length;
  const stack = []; // will store { char, index } for open brackets

  while (i < len) {
    const ch = text[i];

    // Check for string literals: '...' or "..."
    if (ch === '\'' || ch === '"') {
      const quote = ch;
      const startQuoteIndex = i;
      i++;
      let terminated = false;
      while (i < len) {
        const c = text[i];
        if (c === '\n' || c === '\r') {
          // Line break inside string is not allowed
          return { ok: false, reason: 'unterminated-string', index: startQuoteIndex };
        }
        if (c === '\\') {
          // Escape character: skip next character if it exists
          i++;
          if (i >= len) {
            // End of text after backslash inside string
            return { ok: false, reason: 'unterminated-string', index: startQuoteIndex };
          }
          if (text[i] === '\n' || text[i] === '\r') {
            return { ok: false, reason: 'unterminated-string', index: startQuoteIndex };
          }
