{"action":"write_file","path":"brackets.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { checkBrackets } = require('./brackets');

test('balanced text', () => {
  assert.deepEqual(checkBrackets('f(a[0], {b: 1})'), { ok: true });
  assert.deepEqual(checkBrackets(''), { ok: true });
});

test('a mismatch', () => {
  assert.deepEqual(checkBrackets('(]'), { ok: false, reason: 'mismatch', index: 1 });
});

test('an unclosed bracket', () => {
  assert.deepEqual(checkBrackets('(('), { ok: false, reason: 'unclosed', index: 1 });
});

test('unexpected closer', () => {
  assert.deepEqual(checkBrackets(')'), { ok: false, reason: 'unexpected-closer', index: 0 });
});

test('unterminated string newline', () => {
  assert.deepEqual(checkBrackets('"abc\ndef"'), { ok: false, reason: 'unterminated-string', index: 0 });
});

test('unterminated string eof', () => {
  assert.deepEqual(checkBrackets('"abc'), { ok: false, reason: 'unterminated-string', index: 0 });
});

test('unterminated comment', () => {
  assert.deepEqual(checkBrackets('/* comment'), { ok: false, reason: 'unterminated-comment', index: 0 });
});

test('strings and comments ignoring brackets', () => {
  assert.deepEqual(checkBrackets('"(]" // (['), { ok: true });
  assert.deepEqual(checkBrackets('/* ([ */ (a)'), { ok: true });
});

test('type error on non-string', () => {
  assert.throws(() => checkBrackets(123), TypeError);
});
"}
